import pty, os, subprocess, time, fcntl, sys, select, json, signal

def run_jplot(env_extra, args, input_lines=None, timeout=3):
    master, slave = pty.openpty()
    env = {"TERM":"xterm-256color", "PATH":"/usr/bin:/bin", "HOME":"/home/agent", "TERM_PROGRAM":"iTerm.app"}
    env.update(env_extra)
    cmd = ["./executable"] + args
    proc = subprocess.Popen(cmd, stdin=slave, stdout=slave, stderr=slave, env=env, close_fds=True)
    os.close(slave)
    fcntl.fcntl(master, fcntl.F_SETFL, os.O_NONBLOCK)
    output = b""
    start = time.time()
    # initial reads
    while time.time()-start < 0.5:
        try:
            data = os.read(master, 4096)
            if not data:
                break
            output+=data
        except BlockingIOError:
            time.sleep(0.05)
        except OSError:
            break

    print("After start output:", output[:1000])

    if input_lines:
        for line in input_lines:
            # write line
            os.write(master, (line+"\n").encode())
            time.sleep(0.2)
            # read available
            for _ in range(5):
                try:
                    d=os.read(master, 8192)
                    output+=d
                except BlockingIOError:
                    break
                except OSError:
                    break
            print("after input line", line, "output tail", output[-2000:])

    # wait a bit more
    time.sleep(0.5)
    try:
        while True:
            d=os.read(master, 8192)
            if not d:
                break
            output+=d
    except:
        pass
    proc.terminate()
    try:
        proc.wait(timeout=1)
    except:
        proc.kill()
    os.close(master)
    return output

