func isTerminal(fd uintptr) bool {
	fi, err := os.NewFile(fd, "").Stat()
	if err != nil {
		return false
	}
	return (fi.Mode() & os.ModeCharDevice) != 0
}

func readWithTimeout(d time.Duration) string {
	ch := make(chan string, 1)
	go func() {
		reader := bufio.NewReader(os.Stdin)
		var buf strings.Builder
		for {
			b, err := reader.ReadByte()
			if err != nil {
				break
			}
			buf.WriteByte(b)
			s := buf.String()
			if strings.Contains(s, "\x1b\\") || strings.HasSuffix(s, "\x07") {
				break
			}
			if strings.HasSuffix(s, "c") && strings.Contains(s, "\x1b[?") {
				break
			}
			if buf.Len() > 200 {
				break
			}
		}
		ch <- buf.String()
	}()
	select {
	case s := <-ch:
		return s
	case <-time.After(d):
		return ""
	}
}

func isSixelSupported(da string) bool {
	start := strings.Index(da, "?")
	end := strings.LastIndex(da, "c")
	if start == -1 || end == -1 || end <= start {
		return false
	}
	mid := da[start+1 : end]
	partsStr := strings.Split(mid, ";")
	nums := []int{}
	for _, p := range partsStr {
		if p == "" {
			continue
		}
		n, err := strconv.Atoi(p)
		if err != nil {
			continue
		}
		nums = append(nums, n)
	}
	if len(nums) < 3 {
		return false
	}
	has4 := false
	for _, n := range nums {
		if n == 4 {
			has4 = true
			break
		}
	}
	if !has4 {
		return false
	}
	first := nums[0]
	if len(nums) == 3 {
		if first >= 62 && nums[1] == 4 {
			return true
		}
		if first == 1 && len(nums) >= 3 && nums[1] == 2 && nums[2] == 4 {
			return true
		}
		return false
	}
	if len(nums) == 4 {
		if first >= 62 && (nums[1] == 4 || nums[2] == 4) {
			return true
		}
		return false
	}
	if len(nums) >= 5 {
		if first >= 62 {
			return true
		}
		return false
	}
	return false
}

func parseReportCellSize(s string) (width, height int, ok bool) {
	// Expected contains "ReportCellSize="
	idx := strings.Index(s, "ReportCellSize=")
	if idx == -1 {
		return 0, 0, false
	}
	rest := s[idx+len("ReportCellSize="):]
	// rest like "8;16\x07" or "8;16;0\x07"
	// trim after BEL or ESC etc
	// Find end
	// Split by non-digit semicolon?
	// Extract up to BEL or ESC or ;
	// Let's find termination
	end := strings.Index(rest, "\x07")
	if end == -1 {
		end = strings.Index(rest, "\x1b")
	}
	if end != -1 {
		rest = rest[:end]
	}
	// Now rest like "8;16" or "8;16;0"
	// Trim spaces
	rest = strings.TrimSpace(rest)
	parts := strings.Split(rest, ";")
	if len(parts) < 2 {
		return 0, 0, false
	}
	// According to observed, first is height, second width
	h, err1 := strconv.Atoi(strings.TrimSpace(parts[0]))
	w, err2 := strconv.Atoi(strings.TrimSpace(parts[1]))
	if err1 != nil || err2 != nil {
		return 0, 0, false
	}
	// Also need to handle third param etc: width is second, height first
	return w, h, true
}

func parse14t(s string) (h, w int, ok bool) {
	// response like "\x1b[4;320;800t"
	start := strings.Index(s, "[4;")
	if start == -1 {
		return 0, 0, false
	}
	rest := s[start+3:]
	end := strings.Index(rest, "t")
	if end == -1 {
		return 0, 0, false
	}
	rest = rest[:end]
	parts := strings.Split(rest, ";")
	if len(parts) < 2 {
		return 0, 0, false
	}
	h, _ = strconv.Atoi(parts[0])
	w, _ = strconv.Atoi(parts[1])
	return h, w, true
}

