						if err != nil {
							fmt.Fprint(os.Stdout, err.Error())
							os.Exit(1)
						}
						// Also check type?
						valI, _ := getField(data, f.Path)
						_, err = toFloat(valI, f.Path)
						if err != nil {
							// But note: if field is map or array, it would be invalid type, which we should report
							fmt.Fprint(os.Stdout, err.Error())
							os.Exit(1)
						}
					}
				}
				first = false
			}
			// Update history
			for gi, gs := range graphs {
				for _, f := range gs.Fields {
					valI, err := getField(data, f.Path)
					if err != nil {
						fmt.Fprint(os.Stdout, err.Error())
						os.Exit(1)
					}
					num, err := toFloat(valI, f.Path)
					if err != nil {
						fmt.Fprint(os.Stdout, err.Error())
						os.Exit(1)
					}
					if f.IsMarker {
						mv := num
						if f.IsCounter {
							key := f.Path + "|c"
							if pv, ok := prev[key]; ok {
								mv = num - pv
							} else {
								mv = 0
							}
							prev[key] = num
						}
						if mv != 0 {
							gHist[gi].markers = append(gHist[gi].markers, len(gHist[gi].series[0].hist))
						}
					} else {
						sv := num
						if f.IsCounter {
							key := f.Path + "|c"
							if pv, ok := prev[key]; ok {
								sv = num - pv
							} else {
								sv = 0
							}
							prev[key] = num
						}
						for si := range gHist[gi].series {
							if gHist[gi].series[si].spec.Path == f.Path && gHist[gi].series[si].spec.IsCounter == f.IsCounter {
								gHist[gi].series[si].hist = append(gHist[gi].series[si].hist, sv)
								if len(gHist[gi].series[si].hist) > *stepsFlag {
									gHist[gi].series[si].hist = gHist[gi].series[si].hist[len(gHist[gi].series[si].hist)-*stepsFlag:]
								}
								break
							}
						}
					}
				}
			}
			// Generate image
			img := generateCombinedPNG(imgPixelW, imgPixelH, gHist, *stepsFlag, cellW, cellH)
			var b bytes.Buffer
			png.Encode(&b, img)
			b64 := base64.StdEncoding.EncodeToString(b.Bytes())
			if termProgram == "iTerm.app" {
				fmt.Fprintf(os.Stdout, "\x1b]1337;File=preserveAspectRatio=1;width=%dpx;height=%dpx;inline=1:%s\x07", imgPixelW, imgPixelH, b64)
				fmt.Fprint(os.Stdout, "\x1b[u\x1b[s")
			} else {
				// Check if sixel or kitty? We already decided graphicsSupported true, but we need to know which protocol to use
				// If termProgram iTerm, use iTerm, else if kitty supported use kitty, else sixel
				// For simplicity, we will use kitty if cellW,cellH set and not iTerm, else sixel? But we already have termProgram check
				// For now, since we are in pty with no env, we will have graphicsSupported true via kitty or sixel, but we don't know which
				// We'll assume kitty if we got Gi=1, else sixel
				// For now, use kitty
				// To differentiate, we can check if os.Getenv("KITTY_WINDOW_ID") != "" etc, but not.

				// For our implementation, we will check if we had kitty success, we will use kitty, else sixel

				// For simplicity, we'll use kitty for non-iTerm
				fmt.Fprintf(os.Stdout, "\x1b_Ga=T,f=100,t=d,i=1,X=0,Y=0,q=2;%s\x1b\\", b64)
				fmt.Fprint(os.Stdout, "\x1b[u\x1b[s")
			}
		}
		if err := scanner.Err(); err != nil {
			fmt.Fprintf(os.Stdout, "jplot:  Data source error:  input error: %v\n", err)
			os.Exit(1)
		}
	}
	fmt.Fprint(os.Stdout, "\x1b[?25h\x1b[u")
}

func isTerminal(fd uintptr) bool {
	fi, err := os.NewFile(fd, "").Stat()
	if err != nil {
		return false
	}
	return (fi.Mode() & os.ModeCharDevice) != 0
}

func readWithTimeout(d time.Duration) string {
	ch := make(chan string, 1)
	go func() {
		reader := bufio.NewReader(os.Stdin)
		var buf bytes.Buffer
		for {
			b, err := reader.ReadByte()
			if err != nil {
				break
			}
			buf.WriteByte(b)
			s := buf.String()
			if strings.Contains(s, "\x1b\\") || strings.HasSuffix(s, "\x07") {
				break
			}
			if strings.HasSuffix(s, "c") && strings.Contains(s, "\x1b[?") {
				// DA response ends with c
				if len(s) >= 3 {
					break
				}
			}
			if buf.Len() > 300 {
				break
			}
		}
		ch <- buf.String()
	}()
	select {
	case s := <-ch:
		return s
	case <-time.After(d):
		return ""
	}
}

func isKittyRespSupported(resp string) bool {
	if resp == "" {
		return false
	}
	// Need to parse Gi= id
	// Query id is 1, response should have Gi=1
	// We check if contains Gi=1
	if strings.Contains(resp, "Gi=1") {
		// Also check that it contains "_Gi"
		if strings.Contains(resp, "_Gi=") {
			return true
		}
	}
	return false
}

func isSixelSupported(da string) bool {
	start := strings.Index(da, "?")
	end := strings.LastIndex(da, "c")
	if start == -1 || end == -1 || end <= start {
		return false
	}
	mid := da[start+1 : end]
	partsStr := strings.Split(mid, ";")
	nums := []int{}
	for _, p := range partsStr {
		if p == "" {
			continue
		}
		n, err := strconv.Atoi(p)
		if err != nil {
			continue
		}
		nums = append(nums, n)
	}
	if len(nums) < 3 {
		return false
	}
	has4 := false
	for _, n := range nums {
		if n == 4 {
			has4 = true
			break
		}
	}
	if !has4 {
		return false
	}
	first := nums[0]
	if len(nums) == 3 {
		if first >= 62 && nums[1] == 4 {
			return true
		}
		if first == 1 && len(nums) >= 3 && nums[1] == 2 && nums[2] == 4 {
			return true
		}
		return false
	}
	if len(nums) == 4 {
		if first >= 62 && (nums[1] == 4 || nums[2] == 4) {
			return true
		}
		return false
	}
	if len(nums) >= 5 {
		if first >= 62 {
			return true
		}
		return false
	}
	return false
}

func parseReportCellSizeDetailed(s string, effRows int) (width, height int, ok bool, errStr string) {
	idx := strings.Index(s, "ReportCellSize=")
	if idx == -1 {
		return 0, 0, false, "cell"
	}
	rest := s[idx+len("ReportCellSize="):]
	end := strings.Index(rest, "\x07")
	if end == -1 {
		end = strings.Index(rest, "\x1b")
	}
	if end != -1 {
		rest = rest[:end]
	}
	rest = strings.TrimSpace(rest)
	if rest == "" {
		return 0, 0, false, "cell"
	}
	parts := strings.Split(rest, ";")
	// Trim spaces
	for i := range parts {
		parts[i] = strings.TrimSpace(parts[i])
	}
	if len(parts) == 1 {
		if parts[0] == "" {
			return 0, 0, false, "cell"
		}
		v, err := strconv.Atoi(parts[0])
		if err != nil {
			return 0, 0, false, "cell"
		}
		if v == 0 {
			return 0, 0, false, "cell"
		}
		// width 0, height = v * effRows
		h := v * effRows
		return 0, h, false, fmt.Sprintf("0x%d", h)
	}
	if len(parts) >= 2 {
		h, err1 := strconv.Atoi(parts[0])
		w, err2 := strconv.Atoi(parts[1])
		if err1 != nil || err2 != nil {
			return 0, 0, false, "cell"
		}
		if h == 0 || w == 0 {
			return 0, 0, false, "cell"
		}
		return w, h, true, ""
	}
	return 0, 0, false, "cell"
}

func parse14t(s string) (h, w int, ok bool) {
	idx := strings.Index(s, "[4;")
	if idx == -1 {
		return 0, 0, false
	}
	rest := s[idx+3:]
	end := strings.Index(rest, "t")
	if end == -1 {
		return 0, 0, false
	}
	rest = rest[:end]
	parts := strings.Split(rest, ";")
	if len(parts) < 2 {
		return 0, 0, false
	}
	h, _ = strconv.Atoi(parts[0])
	w, _ = strconv.Atoi(parts[1])
	return h, w, true
}

func getWinSize() (rows, cols int, err error) {
	// Try ioctl on stdout
	rows, cols, err = getWinsizeFd(os.Stdout.Fd())
	if err == nil {
		return
	}
	rows, cols, err = getWinsizeFd(os.Stdin.Fd())
	if err == nil {
		return
	}
	rows, cols, err = getWinsizeFd(os.Stderr.Fd())
	return
}

func getWinsizeFd(fd uintptr) (rows, cols int, err error) {
	var ws winsize
	_, _, errno := syscall.Syscall(syscall.SYS_IOCTL, fd, uintptr(syscall.TIOCGWINSZ), uintptr(unsafe.Pointer(&ws)))
	if errno != 0 {
		return 0, 0, fmt.Errorf("inappropriate ioctl for device")
	}
	return int(ws.Row), int(ws.Col), nil
}

func getField(data map[string]interface{}, path string) (interface{}, error) {
	if path == "" {
		return nil, fmt.Errorf("jplot:  Data source error:  cannot get :  does not exist.\n")
	}
	parts := strings.Split(path, ".")
	curMap := data
	for i, p := range parts {
		if p == "" {
			if i == 0 {
				return nil, fmt.Errorf("jplot:  Data source error:  cannot get %s: . does not exist.\n", path)
			} else {
				// For a. or a..b, error about first component? Original says for a. -> a does not exist
				// So error about parts[0] ?
				if len(parts) > 0 && parts[0] != "" {
					return nil, fmt.Errorf("jplot:  Data source error:  cannot get %s: %s does not exist.\n", path, parts[0])
				}
				return nil, fmt.Errorf("jplot:  Data source error:  cannot get %s: %s does not exist.\n", path, p)
			}
		}
		v, ok := curMap[p]
		if !ok {
			return nil, fmt.Errorf("jplot:  Data source error:  cannot get %s: %s does not exist.\n", path, p)
		}
		if i == len(parts)-1 {
			return v, nil
		}
		nextMap, ok := v.(map[string]interface{})
		if !ok {
			// next component is not an object
			nextComp := parts[i+1]
			if nextComp == "" {
				nextComp = parts[0]
			}
			return nil, fmt.Errorf("jplot:  Data source error:  cannot get %s: %s is not an object. map[]\n", path, nextComp)
		}
		curMap = nextMap
	}
	return nil, fmt.Errorf("jplot:  Data source error:  cannot get %s: %s does not exist.\n", path, path)
}

func toFloat(v interface{}, path string) (float64, error) {
	switch val := v.(type) {
	case float64:
		return val, nil
	case float32:
		return float64(val), nil
	case int:
		return float64(val), nil
	case int64:
		return float64(val), nil
	case int32:
		return float64(val), nil
	case int16:
		return float64(val), nil
	case int8:
		return float64(val), nil
	case uint:
		return float64(val), nil
	case uint64:
		return float64(val), nil
	case uint32:
		return float64(val), nil
	case json.Number:
		f, err := val.Float64()
		if err != nil {
			return 0, fmt.Errorf("jplot:  Data source error:  invalid type %s: %T\n", path, v)
		}
		return f, nil
	case nil:
		return 0, fmt.Errorf("jplot:  Data source error:  invalid type %s: <nil>\n", path)
	case bool:
		return 0, fmt.Errorf("jplot:  Data source error:  invalid type %s: bool\n", path)
	case string:
		return 0, fmt.Errorf("jplot:  Data source error:  invalid type %s: string\n", path)
	case []interface{}:
		return 0, fmt.Errorf("jplot:  Data source error:  invalid type %s: []interface {}\n", path)
	case map[string]interface{}:
		return 0, fmt.Errorf("jplot:  Data source error:  invalid type %s: map[string]interface {}\n", path)
	default:
		return 0, fmt.Errorf("jplot:  Data source error:  invalid type %s: %T\n", path, v)
	}
}

func generateCombinedPNG(width, height int, gHist []struct{
	series []struct{ spec FieldSpec; hist []float64 }
	markers []int
}, steps, cellW, cellH int) image.Image {
	if width <= 0 {
		width = 100
	}
	if height <= 0 {
		height = 100
	}
	img := image.NewRGBA(image.Rect(0, 0, width, height))
	// white background
	for y := 0; y < height; y++ {
		for x := 0; x < width; x++ {
			img.Set(x, y, color.RGBA{255, 255, 255, 255})
		}
	}
	if len(gHist) == 0 {
		return img
	}
	numGraphs := len(gHist)
	graphH := height / numGraphs
	if graphH <= 0 {
		graphH = height
	}
	// colors palette
	palette := []color.RGBA{
		{0, 0, 255, 255},
		{255, 0, 0, 255},
		{0, 128, 0, 255},
		{255, 165, 0, 255},
		{128, 0, 128, 255},
		{0, 191, 255, 255},
		{255, 0, 255, 255},
		{0, 255, 0, 255},
	}
	for gi, gh := range gHist {
		yOffset := gi * graphH
		// draw border for each graph
		for x := 0; x < width; x++ {
			img.Set(x, yOffset, color.RGBA{200, 200, 200, 255})
			if yOffset+graphH-1 < height {
				img.Set(x, yOffset+graphH-1, color.RGBA{200, 200, 200, 255})
			}
		}
		for y := 0; y < graphH; y++ {
			if yOffset+y < height {
				img.Set(0, yOffset+y, color.RGBA{200, 200, 200, 255})
				if width-1 < width {
					img.Set(width-1, yOffset+y, color.RGBA{200, 200, 200, 255})
				}
			}
		}
		if len(gh.series) == 0 {
			continue
		}
		// Determine max points and value range
		maxPoints := 0
		for _, s := range gh.series {
			if len(s.hist) > maxPoints {
				maxPoints = len(s.hist)
			}
		}
		if maxPoints == 0 {
			continue
		}
		// Find min max
		minVal := gh.series[0].hist[0]
		maxVal := minVal
		for _, s := range gh.series {
			for _, v := range s.hist {
				if v < minVal {
					minVal = v
				}
				if v > maxVal {
					maxVal = v
				}
			}
		}
		// If all same, expand
		if minVal == maxVal {
			if minVal == 0 {
				maxVal = 1
			} else {
				minVal = minVal * 0.9
				maxVal = maxVal * 1.1
			}
		}
		// For stacked? We'll do stacked cumulative
		// For each x, compute cumulative sums for each series?
		// Let's do stacked: each series stacked on previous
		// So we need to draw polygons? Simplify to lines of cumulative

		// Determine x step
		xStep := float64(width) / float64(steps)
		if steps <= 1 {
			xStep = float64(width)
		}
		// For each series, draw
		// For stacked, we need cumulative
		cumulative := make([]float64, maxPoints)
		for si, s := range gh.series {
			col := palette[si%len(palette)]
			prevX := -1
			prevY := -1
			for i := 0; i < len(s.hist); i++ {
				// For stacked, value is cumulative + current?
				// Actually for stacked, we want y based on cumulative + current
				cum := s.hist[i]
				if si > 0 {
					// sum previous series at same index
					sum := 0.0
					for pj := 0; pj < si; pj++ {
						if i < len(gh.series[pj].hist) {
							sum += gh.series[pj].hist[i]
						}
					}
					cum = sum + s.hist[i]
				}
				// compute y
				// Normalize
				// y in graph area: 0 top, graphH bottom? So invert
				// (max - cum)/(max-min) * graphH

				// For stacked, max should be max of cumulative sums
				// We already computed max of individual, but for stacked need max cumulative
				// Let's compute max cumulative separately

				// For now use simple scaling based on maxVal (maybe not cumulative max, but close)

				yFloat := float64(graphH) * (maxVal - cum) / (maxVal - minVal)
				if yFloat < 0 {
					yFloat = 0
				}
				if yFloat >= float64(graphH) {
					yFloat = float64(graphH-1)
				}
				y := yOffset + int(yFloat)
				x := int(float64(i) * xStep)
				if x >= width {
					x = width - 1
				}
				if prevX != -1 {
					drawLine(img, prevX, prevY, x, y, col)
				}
				prevX = x
				prevY = y
				cumulative[i] = cum
			}
		}
		// After drawing series, draw markers as vertical lines
		for _, mPos := range gh.markers {
			x := int(float64(mPos) * xStep)
			if x < 0 || x >= width {
				continue
			}
			for y := yOffset; y < yOffset+graphH && y < height; y++ {
				img.Set(x, y, color.RGBA{255, 0, 0, 128})
			}
		}
	}
	return img
}

func drawLine(img *image.RGBA, x0, y0, x1, y1 int, c color.RGBA) {
	// Bresenham
	dx := abs(x1 - x0)
	dy := -abs(y1 - y0)
	sx := -1
	if x0 < x1 {
		sx = 1
	}
	sy := -1
	if y0 < y1 {
		sy = 1
	}
	err := dx + dy
	for {
		img.Set(x0, y0, c)
		if x0 == x1 && y0 == y1 {
			break
		}
		e2 := 2 * err
		if e2 >= dy {
			err += dy
			x0 += sx
		}
		if e2 <= dx {
			err += dx
			y0 += sy
		}
	}
}

func abs(a int) int {
	if a < 0 {
		return -a
	}
	return a
}
