	if resp == "" {
		return false
	}
	if strings.Contains(resp, "Gi=1") && strings.Contains(resp, "_Gi=") {
		return true
	}
	return false
}

func isSixelSupported(da string) bool {
	start := strings.Index(da, "?")
	end := strings.LastIndex(da, "c")
	if start == -1 || end == -1 || end <= start {
		return false
	}
	mid := da[start+1 : end]
	partsStr := strings.Split(mid, ";")
	nums := []int{}
	for _, p := range partsStr {
		if p == "" {
			continue
		}
		n, err := strconv.Atoi(p)
		if err != nil {
			continue
		}
		nums = append(nums, n)
	}
	if len(nums) < 3 {
		return false
	}
	has4 := false
	for _, n := range nums {
		if n == 4 {
			has4 = true
			break
		}
	}
	if !has4 {
		return false
	}
	first := nums[0]
	if len(nums) == 3 {
		if first >= 62 && nums[1] == 4 {
			return true
		}
		if first == 1 && len(nums) >= 3 && nums[1] == 2 && nums[2] == 4 {
			return true
		}
		return false
	}
	if len(nums) == 4 {
		if first >= 62 && (nums[1] == 4 || nums[2] == 4) {
			return true
		}
		return false
	}
	if len(nums) >= 5 {
		if first >= 62 {
			return true
		}
		return false
	}
	return false
}

