			fmt.Fprintf(os.Stdout, "jplot:  Data source error:  input error: %v\n", err)
			os.Exit(1)
		}
		if line == "" && err == io.EOF {
			// empty, no first data
		} else {
			trim := strings.TrimSpace(line)
			if trim != "" {
				var data map[string]interface{}
				if err := json.Unmarshal([]byte(trim), &data); err != nil {
					fmt.Fprintf(os.Stdout, "jplot:  Data source error:  input error: %v\n", err)
					os.Exit(1)
				}
				firstDataMap = data
				for _, gs := range graphs {
					for _, f := range gs.Fields {
						_, err := getField(data, f.Path)
						if err != nil {
							fmt.Fprint(os.Stdout, err.Error())
							os.Exit(1)
						}
						valI, _ := getField(data, f.Path)
						_, err = toFloat(valI, f.Path)
						if err != nil {
							fmt.Fprint(os.Stdout, err.Error())
							os.Exit(1)
						}
					}
				}
			}
			// Keep the first line for later processing by storing it and using a combined reader
			// We'll create a new reader that first returns the already read line, then continues
			remaining, _ := io.ReadAll(reader) // This will block until EOF if more data not yet available, so we should not do ReadAll here
			// Instead, we'll keep the original reader and handle first line separately in loop
			// For simplicity, we will store first line and then in loop we will process it first, then continue reading from reader
			_ = remaining
		}
	}

