			}
			// Now window size check
			fmt.Fprint(os.Stdout, "jplot:  Cannot get window size:  inappropriate ioctl for device\n")
			os.Exit(1)
		}
		// For tty, we have not yet validated first data; we will do after window size
	}

	if !isTTYOut {
		fmt.Fprint(os.Stdout, "jplot:  Cannot get window size:  inappropriate ioctl for device\n")
		os.Exit(1)
	}

	tRows, tCols, err := getWinSize()
