				fmt.Fprint(os.Stdout, "\x1b[u\x1b[s")
			} else {
				fmt.Fprintf(os.Stdout, "\x1b_Ga=T,f=100,t=d,i=1,X=0,Y=0,q=2;%s\x1b\\", b64)
				fmt.Fprint(os.Stdout, "\x1b[u\x1b[s")
			}
			<-ticker.C
		}
	} else {
		if reader == nil {
			reader = bufio.NewReader(os.Stdin)
		}
		prev := make(map[string]float64)
		var gHist []graphHist
		for _, gs := range graphs {
			gh := graphHist{}
			for _, f := range gs.Fields {
				if f.IsMarker {
					continue
				}
				gh.series = append(gh.series, seriesHist{spec: f})
			}
			gHist = append(gHist, gh)
		}
		// If we had firstDataMap from earlier non-tty path, we already exited. So for tty path, firstDataMap is set from earlier read? Actually for tty path we didn't read first data yet. So firstDataMap is still set from earlier? In tty path, we didn't read earlier, we only read for non-tty. So for tty, firstDataMap is nil.

		// For tty path, we need to handle blank initial render? Original renders blank right after cell size query, before any data. We have already done the query and are about to enter loop. Let's render blank once before reading data, to match original.

		if firstDataMap == nil {
			// Render blank
			img := generateCombinedPNG(imgPixelW, imgPixelH, gHist, *stepsFlag, cellW, cellH)
			var b bytes.Buffer
			png.Encode(&b, img)
			b64 := base64.StdEncoding.EncodeToString(b.Bytes())
			if termProgram == "iTerm.app" {
				fmt.Fprintf(os.Stdout, "\x1b]1337;File=preserveAspectRatio=1;width=%dpx;height=%dpx;inline=1:%s\x07", imgPixelW, imgPixelH, b64)
				fmt.Fprint(os.Stdout, "\x1b[u\x1b[s")
			} else if isKitty {
				fmt.Fprintf(os.Stdout, "\x1b_Ga=T,f=100,t=d,i=2,X=0,Y=0,q=2;%s\x1b\\", b64)
				fmt.Fprint(os.Stdout, "\x1b[u\x1b[s")
			} else if isSixel {
				fmt.Fprint(os.Stdout, generateSixelPlaceholder(imgPixelW, imgPixelH))
				fmt.Fprint(os.Stdout, "\x1b[u\x1b[s")
			}
		}

		first := true
		for {
			line, err := reader.ReadString('\n')
