							first = false
						}
						updateHist(&gHist, graphs, data, prev)
						img := generateCombinedPNG(imgPixelW, imgPixelH, gHist, *stepsFlag, cellW, cellH)
						var b bytes.Buffer
						png.Encode(&b, img)
						b64 := base64.StdEncoding.EncodeToString(b.Bytes())
						if termProgram == "iTerm.app" {
							fmt.Fprintf(os.Stdout, "\x1b]1337;File=preserveAspectRatio=1;width=%dpx;height=%dpx;inline=1:%s\x07", imgPixelW, imgPixelH, b64)
							fmt.Fprint(os.Stdout, "\x1b[u\x1b[s")
						} else if isKitty {
							fmt.Fprintf(os.Stdout, "\x1b_Ga=T,f=100,t=d,i=1,X=0,Y=0,q=2;%s\x1b\\", b64)
