                if b"ReportCellSize" in d and not saw:
                    saw=True
                    os.write(master, b"\x1b]1337;ReportCellSize=8;16\x07")
                    break
        except BlockingIOError:
            time.sleep(0.1)
    time.sleep(0.5)
    try:
        while True:
            d=os.read(master, 8192)
            if not d:
                break
            out+=d
    except:
        pass
    for line in inputs:
        try:
            proc.stdin.write((line+"\n").encode())
            proc.stdin.flush()
        except:
            break
        time.sleep(0.4)
        try:
            while True:
                d=os.read(master, 8192)
                if not d:
                    break
                out+=d
        except:
