		}
		if minVal == maxVal {
			if minVal == 0 {
				maxVal = 1
			} else {
				minVal *= 0.9
				maxVal *= 1.1
				if minVal == maxVal {
					maxVal = minVal + 1
				}
			}
		}
		xStep := float64(width) / float64(steps)
		if steps <= 1 {
			xStep = float64(width)
		}
		if xStep <= 0 {
			xStep = 1
		}
		for si, s := range gh.series {
			col := palette[si%len(palette)]
			var prevX, prevY int
			firstPoint := true
			for i := 0; i < len(s.hist); i++ {
