}, graphs []GraphSpec, data map[string]interface{}, prev map[string]float64) {
	for gi, gs := range graphs {
		for _, f := range gs.Fields {
			valI, _ := getField(data, f.Path)
			num, _ := toFloat(valI, f.Path)
			if f.IsMarker {
