func updateHistGeneric(gHist *[]struct {
	series []struct {
		spec FieldSpec
		hist []float64
	}
	markers []int
}, graphs []GraphSpec, data map[string]interface{}, prev map[string]float64) {
	for gi, gs := range graphs {
		for _, f := range gs.Fields {
			valI, _ := getField(data, f.Path)
			num, _ := toFloat(valI, f.Path)
			if f.IsMarker {
				mv := num
				if f.IsCounter {
					key := f.Path + "|c"
					if pv, ok := prev[key]; ok {
						mv = num - pv
					} else {
						mv = 0
					}
					prev[key] = num
				}
				if mv != 0 {
