def set_winsize(fd, rows, cols):
    winsz = struct.pack('HHHH', rows, cols, 0, 0)
    fcntl.ioctl(fd, termios.TIOCSWINSZ, winsz)

master, slave = pty.openpty()
set_winsize(master, 20, 100)
env={"TERM":"xterm-256color","PATH":"/usr/bin:/bin","HOME":"/home/agent","TERM_PROGRAM":"iTerm.app"}
proc = subprocess.Popen(["./executable.new","a"], stdin=subprocess.PIPE, stdout=slave, stderr=slave, env=env, close_fds=True)
os.close(slave)
fcntl.fcntl(master, fcntl.F_SETFL, os.O_NONBLOCK)
out=b""
start=time.time()
while time.time()-start < 5:
    try:
        d=os.read(master, 8192)
        if d:
            out+=d
            print(f"READ len={len(d)} {d[:500]!r}")
            if b"ReportCellSize" in d and b"File=" not in d:
                print("Sending 8;16")
                os.write(master, b"\x1b]1337;ReportCellSize=8;16\x07")
    except BlockingIOError:
        time.sleep(0.1)
    except OSError:
        break
time.sleep(1)
try:
    while True:
        d=os.read(master, 8192)
        if not d:
            break
        out+=d
        print(f"TAIL len={len(d)} {d[:500]!r}")
except:
    pass
print(f"FINAL len {len(out)} has File={b'File=' in out}")
proc.terminate()
try:
    proc.wait(timeout=1)
except:
    proc.kill()
os.close(master)
PY
