            print(f"READ len={len(d)} File={b'File=' in d} {d[:500]!r}")
            if b"ReportCellSize" in d and b"File=" not in d:
                print("Sending 8;16")
                os.write(master, b"\x1b]1337;ReportCellSize=8;16\x07")
    except BlockingIOError:
        time.sleep(0.1)
    except OSError:
        break
time.sleep(1)
try:
    while True:
        d=os.read(master, 8192)
        if not d:
            break
        out+=d
        print(f"TAIL len={len(d)} File={b'File=' in d} {d[:500]!r}")
except:
    pass
print(f"FINAL len {len(out)} File={b'File=' in out}")
proc.terminate()
try:
    proc.wait(timeout=1)
except:
    proc.kill()
os.close(master)
PY
"}

