			b, err := r.ReadByte()
			if err!=nil {
				fmt.Fprintf(os.Stderr, "stdin reader err %v\n", err)
				break
			}
			buf.WriteByte(b)
			fmt.Fprintf(os.Stderr, "stdin reader byte %q buf %q\n", b, buf.String())
			if strings.Contains(buf.String(), "\x07") {
				break
			}
		}
	}()
	// Also try reading from stdout
	go func() {
		var buf bytes.Buffer
		tmp := make([]byte, 1024)
		for {
			n, err := syscall.Read(int(os.Stdout.Fd()), tmp)
			if n>0 {
				buf.Write(tmp[:n])
				fmt.Fprintf(os.Stderr, "stdout read %q\n", buf.String())
				if strings.Contains(buf.String(), "\x07") {
					break
				}
			}
			if err!=nil {
				time.Sleep(10*time.Millisecond)
			}
		}
	}()
	time.Sleep(5*time.Second)
}

func isTerm(fd uintptr) bool {
	fi, err := os.NewFile(fd, "").Stat()
	if err!=nil {return false}
	return (fi.Mode() & os.ModeCharDevice)!=0
}
