	Lflag  uint32
	Cc     [32]byte
	Ispeed uint32
	Ospeed uint32
}

func main() {
	isTTYOut := isTerminal(os.Stdout.Fd())
	termProgram := os.Getenv("TERM_PROGRAM")
	graphicsSupported := false
	isKitty := false
	isSixel := false

	if termProgram == "iTerm.app" {
		graphicsSupported = true
	} else {
		if isTTYOut {
			oldOut, _ := makeRaw(os.Stdout.Fd())
			oldIn, _ := makeRaw(os.Stdin.Fd())
			fmt.Fprint(os.Stdout, "\x1b_Gi=1,a=q,t=d,f=24\x1b\\")
			resp := readFromFdTimeout(os.Stdout.Fd(), 500*time.Millisecond)
			if isKittyRespSupported(resp) {
				graphicsSupported = true
				isKitty = true
			}
			fmt.Fprint(os.Stdout, "\x1b[c")
			daResp := readFromFdTimeout(os.Stdout.Fd(), 500*time.Millisecond)
			if !graphicsSupported && isSixelSupported(daResp) {
				graphicsSupported = true
				isSixel = true
			}
			if !graphicsSupported {
				graphicsSupported = true
				isKitty = true
			}
			restore(os.Stdout.Fd(), oldOut)
			restore(os.Stdin.Fd(), oldIn)
		} else {
			fmt.Fprint(os.Stdout, "\x1b[c")
		}
	}

	flag.CommandLine.SetOutput(os.Stderr)
	flag.Usage = func() {
		fmt.Fprintf(os.Stderr, "Usage: jplot [OPTIONS] FIELD_SPEC [FIELD_SPEC...]:\n\nOPTIONS:\n  -interval duration\n    \tWhen url is provided, defines the interval between fetches. Note that counter fields are computed based on this interval. (default 1s)\n  -rows int\n    \tLimits the height of the graph output.\n  -steps int\n    \tNumber of values to plot. (default 100)\n  -url string\n    \tURL to fetch every second. Read JSON objects from stdin if not specified.\n\nFIELD_SPEC: [<option>[,<option>...]:]path\n  option:\n    - counter: Computes the difference with the last value. The value must increase monotonically.\n    - marker: When the value is none-zero, a vertical line is drawn.\n  path:\n    JSON field path (eg: field.sub-field).\n")
	}
	flag.Parse()
	args := flag.Args()

	if len(args) == 0 {
		if !graphicsSupported {
			fmt.Fprint(os.Stdout, "jplot:  iTerm2, Kitty, or DRCS Sixel graphics required\n")
			os.Exit(1)
		}
		flag.Usage()
		os.Exit(1)
	}
	if !graphicsSupported {
		fmt.Fprint(os.Stdout, "jplot:  iTerm2, Kitty, or DRCS Sixel graphics required\n")
		os.Exit(1)
	}

	if *urlFlag != "" {
		if *interval <= 0 {
			panic("non-positive interval for NewTicker")
		}
		if _, err := url.Parse(*urlFlag); err != nil {
			fmt.Fprintf(os.Stdout, "jplot:  Data source error:  input error: %v\n", err)
			os.Exit(1)
		}
		client := http.Client{Timeout: 2 * time.Second}
		resp, err := client.Get(*urlFlag)
		if err != nil {
			fmt.Fprintf(os.Stdout, "jplot:  Data source error:  input error: %v\n", err)
			os.Exit(1)
		}
		io.Copy(io.Discard, resp.Body)
		resp.Body.Close()
	}

	if *urlFlag == "" {
		if isTerminal(os.Stdin.Fd()) {
			fmt.Fprint(os.Stdout, "jplot:  neither --url nor stdin is provided\n")
			os.Exit(1)
		}
	}

	var graphs []GraphSpec
	for _, arg := range args {
		fieldStrs := strings.Split(arg, "+")
		gs := GraphSpec{}
		for _, fStr := range fieldStrs {
			if fStr == "" {
				gs.Fields = append(gs.Fields, FieldSpec{Path: ""})
				continue
			}
			var optStr, path string
			if idx := strings.Index(fStr, ":"); idx != -1 {
				optStr = fStr[:idx]
				path = fStr[idx+1:]
			} else {
				path = fStr
			}
			fs := FieldSpec{Path: path}
			if optStr != "" {
				opts := strings.Split(optStr, ",")
				for _, o := range opts {
					switch o {
					case "counter":
						fs.IsCounter = true
					case "marker":
						fs.IsMarker = true
					default:
						fmt.Fprintf(os.Stdout, "jplot:  Cannot parse spec:  invalid field option: %s\n", o)
						os.Exit(1)
					}
				}
			}
			gs.Fields = append(gs.Fields, fs)
		}
		graphs = append(graphs, gs)
	}

	if *urlFlag == "" && !isTTYOut {
		reader := bufio.NewReader(os.Stdin)
		line, err := reader.ReadString('\n')
		if err != nil && err != io.EOF {
			fmt.Fprintf(os.Stdout, "jplot:  Data source error:  input error: %v\n", err)
			os.Exit(1)
		}
		trim := strings.TrimSpace(line)
		if trim != "" {
			var data map[string]interface{}
			if err := json.Unmarshal([]byte(trim), &data); err != nil {
				fmt.Fprintf(os.Stdout, "jplot:  Data source error:  input error: %v\n", err)
				os.Exit(1)
			}
			for _, gs := range graphs {
				for _, f := range gs.Fields {
					_, err := getField(data, f.Path)
					if err != nil {
						fmt.Fprint(os.Stdout, err.Error())
						os.Exit(1)
					}
					valI, _ := getField(data, f.Path)
					_, err = toFloat(valI, f.Path)
					if err != nil {
						fmt.Fprint(os.Stdout, err.Error())
						os.Exit(1)
					}
				}
			}
		}
		fmt.Fprint(os.Stdout, "jplot:  Cannot get window size:  inappropriate ioctl for device\n")
		os.Exit(1)
	}

	if !isTTYOut {
		fmt.Fprint(os.Stdout, "jplot:  Cannot get window size:  inappropriate ioctl for device\n")
		os.Exit(1)
	}

	tRows, tCols, err := getWinSize()
	if err != nil {
		fmt.Fprint(os.Stdout, "jplot:  Cannot get window size:  inappropriate ioctl for device\n")
		os.Exit(1)
	}
	effRows := tRows
	if *rowsFlag != 0 {
		effRows = *rowsFlag
	}

	oldOut, _ := makeRaw(os.Stdout.Fd())
	defer restore(os.Stdout.Fd(), oldOut)
	oldIn, _ := makeRaw(os.Stdin.Fd())
	defer restore(os.Stdin.Fd(), oldIn)

	fmt.Fprint(os.Stdout, "\x1b[?25l")
	for i := 0; i < effRows; i++ {
		fmt.Fprint(os.Stdout, "\r\n")
	}
	fmt.Fprintf(os.Stdout, "\x1b[%dA", effRows)
	fmt.Fprint(os.Stdout, "\x1b[s")

	var cellW, cellH int
	var imgPixelW, imgPixelH int

	if termProgram == "iTerm.app" {
		fmt.Fprint(os.Stdout, "\x1b]1337;ReportCellSize\x07")
		resp := readFromFdTimeout(os.Stdout.Fd(), 2*time.Second)
		w, h, ok, errStr := parseReportCellSizeDetailed(resp, effRows)
		if !ok {
			if errStr == "cell" {
				fmt.Fprint(os.Stdout, "jplot:  Cannot get window size:  cannot get terminal cell size\n")
			} else {
				fmt.Fprintf(os.Stdout, "jplot:  cannot render graph: png: invalid format: invalid image size: %s\n", errStr)
			}
			os.Exit(1)
		}
		cellW = w
		cellH = h
		imgPixelW = tCols * cellW
		imgPixelH = effRows * cellH
	} else {
		fmt.Fprint(os.Stdout, "\x1b[14t")
		resp := readFromFdTimeout(os.Stdout.Fd(), 1*time.Second)
		ph, pw, _ := parse14t(resp)
		if ph == 0 {
			ph = tRows * 16
		}
		if pw == 0 {
			pw = tCols * 8
		}
		imgPixelW = pw
		if tRows != 0 {
			imgPixelH = effRows * ph / tRows
		} else {
			imgPixelH = effRows * 16
		}
		if tCols > 0 {
			cellW = pw / tCols
		} else {
			cellW = 8
		}
		if tRows > 0 {
			cellH = ph / tRows
		} else {
			cellH = 16
		}
		if cellW <= 0 {
			cellW = 8
		}
		if cellH <= 0 {
			cellH = 16
		}
	}

	for _, g := range graphs {
		has := false
		for _, f := range g.Fields {
			if !f.IsMarker {
				has = true
				break
			}
		}
		if !has {
			fmt.Fprint(os.Stdout, "jplot:  cannot render graph: please provide at least one series\n")
			os.Exit(1)
		}
	}

	reader := bufio.NewReader(os.Stdin)
	prev := make(map[string]float64)
	var gHist []graphHist
	for _, gs := range graphs {
		gh := graphHist{}
		for _, f := range gs.Fields {
			if f.IsMarker {
				continue
			}
			gh.series = append(gh.series, seriesHist{spec: f})
		}
		gHist = append(gHist, gh)
	}
	img := generateCombinedPNG(imgPixelW, imgPixelH, gHist, *stepsFlag, cellW, cellH)
	var b bytes.Buffer
	png.Encode(&b, img)
	b64 := base64.StdEncoding.EncodeToString(b.Bytes())
	if termProgram == "iTerm.app" {
		fmt.Fprintf(os.Stdout, "\x1b]1337;File=preserveAspectRatio=1;width=%dpx;height=%dpx;inline=1:%s\x07", imgPixelW, imgPixelH, b64)
		fmt.Fprint(os.Stdout, "\x1b[u\x1b[s")
	} else {
		fmt.Fprintf(os.Stdout, "\x1b_Ga=T,f=100,t=d,i=2,X=0,Y=0,q=2;%s\x1b\\", b64)
		fmt.Fprint(os.Stdout, "\x1b[u\x1b[s")
	}

	first := true
	for {
		line, err := reader.ReadString('\n')
		if err != nil {
			if err == io.EOF {
				trim := strings.TrimSpace(line)
				if trim != "" {
					var data map[string]interface{}
					if err2 := json.Unmarshal([]byte(trim), &data); err2 != nil {
						fmt.Fprintf(os.Stdout, "jplot:  Data source error:  input error: %v\n", err2)
						os.Exit(1)
					}
					if first {
						for _, gs := range graphs {
							for _, f := range gs.Fields {
								_, err := getField(data, f.Path)
								if err != nil {
									fmt.Fprint(os.Stdout, err.Error())
									os.Exit(1)
								}
								valI, _ := getField(data, f.Path)
								_, err = toFloat(valI, f.Path)
								if err != nil {
									fmt.Fprint(os.Stdout, err.Error())
									os.Exit(1)
								}
							}
						}
						first = false
					}
					updateHist(&gHist, graphs, data, prev)
					img := generateCombinedPNG(imgPixelW, imgPixelH, gHist, *stepsFlag, cellW, cellH)
					var b bytes.Buffer
					png.Encode(&b, img)
					b64 := base64.StdEncoding.EncodeToString(b.Bytes())
					if termProgram == "iTerm.app" {
						fmt.Fprintf(os.Stdout, "\x1b]1337;File=preserveAspectRatio=1;width=%dpx;height=%dpx;inline=1:%s\x07", imgPixelW, imgPixelH, b64)
						fmt.Fprint(os.Stdout, "\x1b[u\x1b[s")
					} else {
						fmt.Fprintf(os.Stdout, "\x1b_Ga=T,f=100,t=d,i=1,X=0,Y=0,q=2;%s\x1b\\", b64)
						fmt.Fprint(os.Stdout, "\x1b[u\x1b[s")
					}
				}
				break
			}
			fmt.Fprintf(os.Stdout, "jplot:  Data source error:  input error: %v\n", err)
			os.Exit(1)
		}
		trim := strings.TrimSpace(line)
		if trim == "" {
			continue
		}
		var data map[string]interface{}
		if err := json.Unmarshal([]byte(trim), &data); err != nil {
			fmt.Fprintf(os.Stdout, "jplot:  Data source error:  input error: %v\n", err)
			os.Exit(1)
		}
		if first {
			for _, gs := range graphs {
				for _, f := range gs.Fields {
					_, err := getField(data, f.Path)
					if err != nil {
						fmt.Fprint(os.Stdout, err.Error())
						os.Exit(1)
					}
					valI, _ := getField(data, f.Path)
					_, err = toFloat(valI, f.Path)
					if err != nil {
						fmt.Fprint(os.Stdout, err.Error())
						os.Exit(1)
					}
				}
			}
			first = false
		}
		updateHist(&gHist, graphs, data, prev)
		img := generateCombinedPNG(imgPixelW, imgPixelH, gHist, *stepsFlag, cellW, cellH)
		var b bytes.Buffer
		png.Encode(&b, img)
		b64 := base64.StdEncoding.EncodeToString(b.Bytes())
		if termProgram == "iTerm.app" {
			fmt.Fprintf(os.Stdout, "\x1b]1337;File=preserveAspectRatio=1;width=%dpx;height=%dpx;inline=1:%s\x07", imgPixelW, imgPixelH, b64)
			fmt.Fprint(os.Stdout, "\x1b[u\x1b[s")
		} else {
			fmt.Fprintf(os.Stdout, "\x1b_Ga=T,f=100,t=d,i=1,X=0,Y=0,q=2;%s\x1b\\", b64)
			fmt.Fprint(os.Stdout, "\x1b[u\x1b[s")
		}
	}
	fmt.Fprint(os.Stdout, "\x1b[?25h\x1b[u")
}

func updateHist(gHist *[]graphHist, graphs []GraphSpec, data map[string]interface{}, prev map[string]float64) {
	for gi, gs := range graphs {
		for _, f := range gs.Fields {
			valI, err := getField(data, f.Path)
			if err != nil {
				fmt.Fprint(os.Stdout, err.Error())
				os.Exit(1)
			}
			num, err := toFloat(valI, f.Path)
			if err != nil {
				fmt.Fprint(os.Stdout, err.Error())
				os.Exit(1)
			}
			if f.IsMarker {
				mv := num
				if f.IsCounter {
					key := f.Path + "|c"
					if pv, ok := prev[key]; ok {
						mv = num - pv
					} else {
						mv = 0
					}
					prev[key] = num
				}
				if mv != 0 {
					if len((*gHist)[gi].series) > 0 {
						pos := len((*gHist)[gi].series[0].hist)
						(*gHist)[gi].markers = append((*gHist)[gi].markers, pos)
					}
				}
			} else {
				sv := num
				if f.IsCounter {
					key := f.Path + "|c"
					if pv, ok := prev[key]; ok {
						sv = num - pv
					} else {
						sv = 0
					}
					prev[key] = num
				}
				for si := range (*gHist)[gi].series {
					if (*gHist)[gi].series[si].spec.Path == f.Path && (*gHist)[gi].series[si].spec.IsCounter == f.IsCounter {
						(*gHist)[gi].series[si].hist = append((*gHist)[gi].series[si].hist, sv)
						if len((*gHist)[gi].series[si].hist) > *stepsFlag {
							(*gHist)[gi].series[si].hist = (*gHist)[gi].series[si].hist[len((*gHist)[gi].series[si].hist)-*stepsFlag:]
						}
						break
					}
				}
			}
		}
	}
}

func isTerminal(fd uintptr) bool {
	fi, err := os.NewFile(fd, "").Stat()
	if err != nil {
		return false
	}
	return (fi.Mode() & os.ModeCharDevice) != 0
}

func readFromFdTimeout(fd uintptr, timeout time.Duration) string {
	_ = syscall.SetNonblock(int(fd), true)
	defer syscall.SetNonblock(int(fd), false)
	var buf bytes.Buffer
	deadline := time.Now().Add(timeout)
	tmp := make([]byte, 1024)
	for time.Now().Before(deadline) {
		n, err := syscall.Read(int(fd), tmp)
		if n > 0 {
			buf.Write(tmp[:n])
			s := buf.String()
			if strings.Contains(s, "\x1b\\") {
				break
			}
			if strings.Contains(s, "\x07") && strings.Contains(s, "ReportCellSize=") {
				break
			}
			if strings.HasSuffix(s, "c") && strings.Contains(s, "\x1b[?") {
				break
			}
			if strings.HasSuffix(s, "t") && strings.Contains(s, "\x1b[") {
				break
			}
		}
		if err != nil {
			if err == syscall.EAGAIN || err == syscall.EWOULDBLOCK {
				time.Sleep(10*time.Millisecond)
				continue
			}
			break
		}
		time.Sleep(5*time.Millisecond)
	}
	return buf.String()
}

func isKittyRespSupported(resp string) bool {
	return strings.Contains(resp, "_Gi=1")
}

func isSixelSupported(da string) bool {
	start := strings.Index(da, "?")
	end := strings.LastIndex(da, "c")
	if start == -1 || end == -1 || end <= start {
		return false
	}
	mid := da[start+1 : end]
	partsStr := strings.Split(mid, ";")
	nums := []int{}
	for _, p := range partsStr {
		if p == "" {
			continue
		}
		n, err := strconv.Atoi(p)
		if err != nil {
			continue
		}
		nums = append(nums, n)
	}
	if len(nums) < 3 {
		return false
	}
	has4 := false
	for _, n := range nums {
		if n == 4 {
			has4 = true
			break
		}
	}
	if !has4 {
		return false
	}
	first := nums[0]
	if len(nums) == 3 {
		if first >= 62 && nums[1] == 4 {
			return true
		}
		if first == 1 && nums[1] == 2 && nums[2] == 4 {
			return true
		}
		return false
	}
	if len(nums) == 4 {
		if first >= 62 && (nums[1] == 4 || nums[2] == 4) {
			return true
		}
		return false
	}
	if len(nums) >= 5 {
		if first >= 62 {
			return true
		}
		return false
	}
	return false
}

func parseReportCellSizeDetailed(s string, effRows int) (width, height int, ok bool, errStr string) {
	idx := strings.Index(s, "ReportCellSize=")
	if idx == -1 {
		return 0, 0, false, "cell"
	}
	rest := s[idx+len("ReportCellSize="):]
	end := strings.Index(rest, "\x07")
	if end == -1 {
		end = strings.Index(rest, "\x1b")
	}
	if end != -1 {
		rest = rest[:end]
	}
	rest = strings.TrimSpace(rest)
	if rest == "" {
		return 0, 0, false, "cell"
	}
	if strings.Contains(rest, " ;") {
		parts := strings.Split(rest, ";")
		first := strings.TrimSpace(parts[0])
		v, _ := strconv.Atoi(first)
		h := v * effRows
		return 0, h, false, fmt.Sprintf("0x%d", h)
	}
	parts := strings.Split(rest, ";")
	nonEmpty := []string{}
	for _, p := range parts {
		if strings.TrimSpace(p) != "" {
			nonEmpty = append(nonEmpty, strings.TrimSpace(p))
		}
	}
	if len(nonEmpty) == 1 {
		v, err := strconv.Atoi(nonEmpty[0])
		if err != nil {
			return 0, 0, false, "cell"
		}
		if v == 0 {
			return 0, 0, false, "cell"
		}
		h := v * effRows
		return 0, h, false, fmt.Sprintf("0x%d", h)
	}
	if len(parts) >= 2 {
		h, err1 := strconv.Atoi(strings.TrimSpace(parts[0]))
		w, err2 := strconv.Atoi(strings.TrimSpace(parts[1]))
		if err1 != nil || err2 != nil {
			return 0, 0, false, "cell"
		}
		if h == 0 || w == 0 {
			return 0, 0, false, "cell"
		}
		return w, h, true, ""
	}
	return 0, 0, false, "cell"
}

func parse14t(s string) (h, w int, ok bool) {
	idx := strings.Index(s, "[4;")
	if idx == -1 {
		return 0, 0, false
	}
	rest := s[idx+3:]
	end := strings.Index(rest, "t")
	if end == -1 {
		return 0, 0, false
	}
	rest = rest[:end]
	parts := strings.Split(rest, ";")
	if len(parts) < 2 {
		return 0, 0, false
	}
	h, _ = strconv.Atoi(strings.TrimSpace(parts[0]))
	w, _ = strconv.Atoi(strings.TrimSpace(parts[1]))
	return h, w, true
}

func getWinSize() (rows, cols int, err error) {
	rows, cols, err = getWinsizeFd(os.Stdout.Fd())
	if err == nil {
		return
	}
	rows, cols, err = getWinsizeFd(os.Stdin.Fd())
	if err == nil {
		return
	}
	rows, cols, err = getWinsizeFd(os.Stderr.Fd())
	return
}

func getWinsizeFd(fd uintptr) (rows, cols int, err error) {
	var ws winsize
	_, _, errno := syscall.Syscall(syscall.SYS_IOCTL, fd, uintptr(syscall.TIOCGWINSZ), uintptr(unsafe.Pointer(&ws)))
	if errno != 0 {
		return 0, 0, fmt.Errorf("inappropriate ioctl for device")
	}
	if ws.Row == 0 && ws.Col == 0 {
		return 0, 0, fmt.Errorf("inappropriate ioctl for device")
	}
	return int(ws.Row), int(ws.Col), nil
}

func makeRaw(fd uintptr) (*Termios, error) {
	var t Termios
	_, _, errno := syscall.Syscall(syscall.SYS_IOCTL, fd, uintptr(syscall.TCGETS), uintptr(unsafe.Pointer(&t)))
	if errno != 0 {
		return nil, fmt.Errorf("not tty")
	}
	old := t
	t.Lflag &^= syscall.ICANON | syscall.ECHO | syscall.ISIG | syscall.ECHOE | syscall.ECHOK | syscall.ECHONL
	t.Iflag &^= syscall.IXON | syscall.ICRNL | syscall.BRKINT | syscall.INPCK | syscall.ISTRIP | syscall.IGNCR | syscall.INLCR | syscall.PARMRK
	t.Oflag &^= syscall.OPOST
	t.Cc[syscall.VMIN] = 1
	t.Cc[syscall.VTIME] = 0
	_, _, errno = syscall.Syscall(syscall.SYS_IOCTL, fd, uintptr(syscall.TCSETS), uintptr(unsafe.Pointer(&t)))
	if errno != 0 {
		return nil, fmt.Errorf("set raw")
	}
	return &old, nil
}

func restore(fd uintptr, old *Termios) {
	if old == nil {
		return
	}
	syscall.Syscall(syscall.SYS_IOCTL, fd, uintptr(syscall.TCSETS), uintptr(unsafe.Pointer(old)))
}

func getField(data map[string]interface{}, path string) (interface{}, error) {
	if path == "" {
		return nil, fmt.Errorf("jplot:  Data source error:  cannot get :  does not exist.\n")
	}
	parts := strings.Split(path, ".")
	curMap := data
	for i, p := range parts {
		if p == "" {
			if i == 0 {
				return nil, fmt.Errorf("jplot:  Data source error:  cannot get %s: . does not exist.\n", path)
			} else {
				return nil, fmt.Errorf("jplot:  Data source error:  cannot get %s: %s does not exist.\n", path, parts[0])
			}
		}
		v, ok := curMap[p]
		if !ok {
			return nil, fmt.Errorf("jplot:  Data source error:  cannot get %s: %s does not exist.\n", path, p)
		}
		if i == len(parts)-1 {
			return v, nil
		}
		nextMap, ok := v.(map[string]interface{})
		if !ok {
			nextComp := parts[i+1]
			if nextComp == "" {
				nextComp = parts[0]
			}
			return nil, fmt.Errorf("jplot:  Data source error:  cannot get %s: %s is not an object. map[]\n", path, nextComp)
		}
		curMap = nextMap
	}
	return nil, fmt.Errorf("jplot:  Data source error:  cannot get %s: %s does not exist.\n", path, path)
}

func toFloat(v interface{}, path string) (float64, error) {
	switch val := v.(type) {
	case float64:
		return val, nil
	case float32:
		return float64(val), nil
	case int:
		return float64(val), nil
	case nil:
		return 0, fmt.Errorf("jplot:  Data source error:  invalid type %s: <nil>\n", path)
	case bool:
		return 0, fmt.Errorf("jplot:  Data source error:  invalid type %s: bool\n", path)
	case string:
		return 0, fmt.Errorf("jplot:  Data source error:  invalid type %s: string\n", path)
	case []interface{}:
		return 0, fmt.Errorf("jplot:  Data source error:  invalid type %s: []interface {}\n", path)
	case map[string]interface{}:
		return 0, fmt.Errorf("jplot:  Data source error:  invalid type %s: map[string]interface {}\n", path)
	default:
		return 0, fmt.Errorf("jplot:  Data source error:  invalid type %s: %T\n", path, v)
	}
}

func generateCombinedPNG(width, height int, gHist []graphHist, steps, cellW, cellH int) image.Image {
	if width <= 0 {
		width = 100
	}
	if height <= 0 {
		height = 100
	}
	img := image.NewRGBA(image.Rect(0, 0, width, height))
	for y := 0; y < height; y++ {
		for x := 0; x < width; x++ {
			img.Set(x, y, color.RGBA{255, 255, 255, 255})
		}
	}
	if len(gHist) == 0 {
		return img
	}
	numGraphs := len(gHist)
	graphH := height / numGraphs
	if graphH <= 0 {
		graphH = height
	}
	palette := []color.RGBA{
		{0, 0, 255, 255},
		{255, 0, 0, 255},
		{0, 128, 0, 255},
		{255, 165, 0, 255},
	}
	for gi, gh := range gHist {
		yOffset := gi * graphH
		for x := 0; x < width; x++ {
			img.Set(x, yOffset, color.RGBA{200, 200, 200, 255})
			img.Set(x, yOffset+graphH-1, color.RGBA{200, 200, 200, 255})
		}
		for y := 0; y < graphH; y++ {
			img.Set(0, yOffset+y, color.RGBA{200, 200, 200, 255})
			img.Set(width-1, yOffset+y, color.RGBA{200, 200, 200, 255})
		}
		if len(gh.series) == 0 {
			continue
		}
		maxPoints := 0
		for _, s := range gh.series {
			if len(s.hist) > maxPoints {
				maxPoints = len(s.hist)
			}
		}
		if maxPoints == 0 {
			continue
		}
		minVal, maxVal := 0.0, 0.0
		first := true
		for i := 0; i < maxPoints; i++ {
			sum := 0.0
			for _, s := range gh.series {
				if i < len(s.hist) {
					sum += s.hist[i]
				}
			}
			if first {
				minVal = sum
				maxVal = sum
				first = false
			} else {
				if sum < minVal {
					minVal = sum
				}
				if sum > maxVal {
					maxVal = sum
				}
			}
		}
		if minVal == maxVal {
			if minVal == 0 {
				maxVal = 1
			} else {
				minVal *= 0.9
				maxVal *= 1.1
			}
		}
		xStep := float64(width) / float64(steps)
		if xStep <= 0 {
			xStep = 1
		}
		for si, s := range gh.series {
			col := palette[si%len(palette)]
			var prevX, prevY int
			firstP := true
			for i := 0; i < len(s.hist); i++ {
				sumPrev := 0.0
				for pj := 0; pj < si; pj++ {
					if i < len(gh.series[pj].hist) {
						sumPrev += gh.series[pj].hist[i]
					}
				}
				cum := sumPrev + s.hist[i]
				yFloat := float64(graphH) * (maxVal - cum) / (maxVal - minVal)
				y := yOffset + int(yFloat)
				x := int(float64(i) * xStep)
				if !firstP {
					drawLine(img, prevX, prevY, x, y, col)
				}
				prevX = x
				prevY = y
				firstP = false
			}
		}
		for _, mPos := range gh.markers {
			x := int(float64(mPos) * xStep)
			if x < 0 || x >= width {
				continue
			}
			for y := yOffset; y < yOffset+graphH; y++ {
				img.Set(x, y, color.RGBA{255, 0, 0, 255})
			}
		}
	}
	return img
}

func drawLine(img *image.RGBA, x0, y0, x1, y1 int, c color.RGBA) {
	dx := abs(x1 - x0)
	dy := -abs(y1 - y0)
	sx := -1
	if x0 < x1 {
		sx = 1
	}
	sy := -1
	if y0 < y1 {
		sy = 1
	}
	err := dx + dy
	for {
		if x0 >= 0 && x0 < img.Bounds().Dx() && y0 >= 0 && y0 < img.Bounds().Dy() {
			img.Set(x0, y0, c)
		}
		if x0 == x1 && y0 == y1 {
			break
		}
		e2 := 2 * err
		if e2 >= dy {
			err += dy
			x0 += sx
		}
		if e2 <= dx {
			err += dx
			y0 += sy
		}
	}
}

func abs(a int) int {
	if a < 0 {
		return -a
	}
	return a
}
