	Oflag uint32
	Cflag uint32
	Lflag uint32
	Cc [32]byte
	Ispeed uint32
	Ospeed uint32
}

func makeRaw(fd uintptr) (*Termios, error) {
	var t Termios
	_, _, errno := syscall.Syscall(syscall.SYS_IOCTL, fd, uintptr(syscall.TCGETS), uintptr(unsafe.Pointer(&t)))
	if errno!=0 {return nil, fmt.Errorf("get")}
	old:=t
	t.Lflag &^= syscall.ICANON|syscall.ECHO|syscall.ISIG
	t.Iflag &^= syscall.IXON|syscall.ICRNL
	t.Oflag &^= syscall.OPOST
	t.Cc[syscall.VMIN]=1
	t.Cc[syscall.VTIME]=0
	_, _, errno = syscall.Syscall(syscall.SYS_IOCTL, fd, uintptr(syscall.TCSETS), uintptr(unsafe.Pointer(&t)))
	if errno!=0 {return nil, fmt.Errorf("set")}
	return &old, nil
}
func restore(fd uintptr, old *Termios) {
	if old==nil {return}
	syscall.Syscall(syscall.SYS_IOCTL, fd, uintptr(syscall.TCSETS), uintptr(unsafe.Pointer(old)))
}
func readFromFdTimeout(fd uintptr, timeout time.Duration) string {
	_ = syscall.SetNonblock(int(fd), true)
	defer syscall.SetNonblock(int(fd), false)
	var buf bytes.Buffer
	deadline := time.Now().Add(timeout)
	tmp := make([]byte, 1024)
	for time.Now().Before(deadline) {
		n, err := syscall.Read(int(fd), tmp)
		if n>0 {
			buf.Write(tmp[:n])
			s:=buf.String()
			fmt.Fprintf(os.Stderr, "readFromFd got %q\n", s)
			if strings.Contains(s, "\x07") || strings.Contains(s, "\x1b\\") {
				break
			}
		}
		if err!=nil {
			if err==syscall.EAGAIN {
				time.Sleep(10*time.Millisecond)
				continue
			}
			break
		}
	}
	return buf.String()
}
func getWinSize() (int,int,error) {
	var ws winsize
	_,_,errno := syscall.Syscall(syscall.SYS_IOCTL, os.Stdout.Fd(), uintptr(syscall.TIOCGWINSZ), uintptr(unsafe.Pointer(&ws)))
	if errno!=0 {return 0,0, fmt.Errorf("ioctl")}
	return int(ws.Row), int(ws.Col), nil
}
