			oldIn, _ := term.MakeRaw(int(os.Stdin.Fd()))
			fmt.Fprint(os.Stdout, "\x1b_Gi=1,a=q,t=d,f=24\x1b\\")
			resp := readFromFdWithTimeout(os.Stdout.Fd(), 400*time.Millisecond)
			if strings.Contains(resp, "_Gi=1") {
				graphicsSupported = true
