	markers []int
}
type Termios struct {
	Iflag  uint32
	Oflag  uint32
	Cflag  uint32
	Lflag  uint32
	Cc     [32]byte
	Ispeed uint32
	Ospeed uint32
}

func main() {
	isTTYOut := isTerminal(os.Stdout.Fd())
	termProgram := os.Getenv("TERM_PROGRAM")
