		}
		if tCols > 0 {
			cellW = pw / tCols
		} else {
			cellW = 8
		}
		if tRows > 0 {
			cellH = ph / tRows
		} else {
			cellH = 16
		}
		if cellW <= 0 {
			cellW = 8
		}
		if cellH <= 0 {
