	}
	img := generateCombinedPNG(imgPixelW, imgPixelH, gHist, *stepsFlag, cellW, cellH)
	var b bytes.Buffer
	png.Encode(&b, img)
	b64 := base64.StdEncoding.EncodeToString(b.Bytes())
	if termProgram == "iTerm.app" {
